<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
$userId=require_auth();$pdo=db();$service=new TripUnifiedInboxService($pdo);$error='';
$tripId=max(0,(int)($_GET['trip']??$_POST['return_trip']??0));$filter=strtolower(trim((string)($_GET['filter']??$_POST['return_filter']??'open')));if(!in_array($filter,['open','unread','resolved','all'],true))$filter='open';$showSettings=!empty($_GET['settings'])||!empty($_POST['return_settings']);
$returnUrl=function()use(&$tripId,&$filter,&$showSettings):string{$q=['filter'=>$filter];if($tripId>0)$q['trip']=$tripId;if($showSettings)$q['settings']=1;return 'trip-inbox.php?'.http_build_query($q);};
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        if(!$service->ready())throw new RuntimeException('Run System Upgrade before using Unified Trip Inbox.');$action=strtolower(trim((string)($_POST['action']??'')));
        if($action==='refresh'){$service->syncUser($userId,$tripId>0?$tripId:null);flash('success','Trip Inbox refreshed from saved Vacation Brain trip systems.');}
        elseif($action==='mark_read'){$service->markRead($userId,(int)($_POST['item_id']??0));}
        elseif($action==='resolve'){$service->resolve($userId,(int)($_POST['item_id']??0));flash('success','Inbox item resolved. The underlying booking, agent, risk, or collaboration record was not changed.');}
        elseif($action==='reopen'){$service->reopen($userId,(int)($_POST['item_id']??0));}
        elseif($action==='snooze'){$service->snooze($userId,(int)($_POST['item_id']??0),(string)($_POST['preset']??''));flash('success','Inbox item snoozed.');}
        elseif($action==='unsnooze'){$service->unsnooze($userId,(int)($_POST['item_id']??0));}
        elseif($action==='save_preferences'){$service->savePreferences($userId,$_POST);flash('success','Trip Inbox delivery preferences saved.');$showSettings=true;}
        elseif($action==='mute_trip'){$tid=(int)($_POST['trip_id']??0);$service->setTripMuted($userId,$tid,true);flash('success','Trip muted from Command Center and agent-attention surfaces. It remains visible inside Trip Inbox.');}
        elseif($action==='unmute_trip'){$tid=(int)($_POST['trip_id']??0);$service->setTripMuted($userId,$tid,false);flash('success','Trip unmuted.');}
        else throw new InvalidArgumentException('Unknown Trip Inbox action.');
        redirect($returnUrl());
    }catch(InvalidArgumentException|OutOfBoundsException|DomainException $e){$error=$e->getMessage();}
    catch(Throwable $e){error_log('Unified Trip Inbox action failed: '.$e->getMessage());$error='Vacation Brain could not complete that Trip Inbox action right now.';}
}
$trips=$service->ready()?$service->accessibleTrips($userId):[];$selectedTrip=null;if($tripId>0){foreach($trips as $t)if((int)$t['id']===$tripId){$selectedTrip=$t;break;}if(!$selectedTrip){$tripId=0;$error=$error?:'That trip is not available in your Trip Inbox.';}}
if($service->ready()){try{$service->syncUser($userId,$tripId>0?$tripId:null);}catch(Throwable $e){error_log('Unified Trip Inbox page sync failed: '.$e->getMessage());$error=$error?:'Trip Inbox loaded, but one or more source systems could not be refreshed right now.';}}
$summary=$service->ready()?$service->summary($userId,$tripId>0?$tripId:null):['unread'=>0,'needs_action'=>0,'now'=>0,'today'=>0,'snoozed'=>0];$threads=$service->ready()?$service->threads($userId,$tripId>0?$tripId:null,$filter,160):[];$prefs=$service->preferences($userId);$success=flash('success');$flashError=flash('trip_inbox_error');if(!$error&&$flashError)$error=$flashError;
$pageStyles=['assets/trip-planning-hub.css','assets/trip-inbox.css'];$title='Trip Inbox — Vacation Brain';
function vb_ti_label(string $v):string{return ucwords(str_replace('_',' ',$v));}
function vb_ti_dt(mixed $v):string{$s=trim((string)$v);if($s==='')return '—';$ts=strtotime($s);return $ts?date('M j · g:i A',$ts):$s;}
function vb_ti_filter_url(string $filter,int $tripId,bool $settings=false):string{$q=['filter'=>$filter];if($tripId>0)$q['trip']=$tripId;if($settings)$q['settings']=1;return app_url('trip-inbox.php?'.http_build_query($q));}
require __DIR__.'/partials/header.php';
?>
