  <?php if($selectedTrip):?><div class="vb-inbox-muted-note"><span><strong><?=e((string)$selectedTrip['name'])?></strong> · <?=e(vb_ti_label((string)$selectedTrip['role']))?><?=!empty($selectedTrip['muted'])?' · muted outside Trip Inbox':' · attention surfaces active'?></span><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=!empty($selectedTrip['muted'])?'unmute_trip':'mute_trip'?>"><input type="hidden" name="trip_id" value="<?=(int)$selectedTrip['id']?>"><input type="hidden" name="return_trip" value="<?=(int)$selectedTrip['id']?>"><input type="hidden" name="return_filter" value="<?=e($filter)?>"><input type="hidden" name="return_settings" value="<?=$showSettings?1:0?>"><button class="button secondary small" type="submit"><?=!empty($selectedTrip['muted'])?'Unmute trip':'Mute trip'?></button></form></div><?php endif;?>

