tripId?>"><input type="hidden" name="return_filter" value="<?=e($filter)?>"><input type="hidden" name="return_settings" value="<?=$showSettings?1:0?>"><button class="button secondary small" type="submit">Reopen</button></form><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="resolve"><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><input type="hidden" name="return_trip" value="<?=$tripId?>"><input type="hidden" name="return_filter" value="<?=e($filter)?>"><input type="hidden" name="return_settings" value="<?=$showSettings?1:0?>"><button class="button secondary small" type="submit">Resolve here</button></form><?php if(!empty($item['snoozed_until'])):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="unsnooze"><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><input type="hidden" name="return_trip" value="<?=$tripId?>"><input type="hidden" name="return_filter" value="<?=e($filter)?>"><input type="hidden" name="return_settings" value="<?=$showSettings?1:0?>"><button class="button secondary small" type="submit">Unsnooze</button></form><?php else:?><details class="vb-inbox-snooze"><summary class="button secondary small">Snooze</summary><div class="vb-inbox-snooze-menu"><?php foreach(['1h'=>'1 hour','tomorrow'=>'Until tomorrow','week'=>'1 week'] as $preset=>$label):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="snooze"><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><input type="hidden" name="preset" value="<?=e($preset)?>"><input type="hidden" name="return_trip" value="<?=$tripId?>"><input type="hidden" name="return_filter" value="<?=e($filter)?>"><input type="hidden" name="return_settings" value="<?=$showSettings?1:0?>"><button type="submit"><?=e($label)?></button></form><?php en